const stableProductId=(uuid:string)=>{let h=2166136261;for(let i=0;i<uuid.length;i++)h=Math.imul(h^uuid.charCodeAt(i),16777619);return (h>>>0)||1};
type PublicListing={id:string;name:string;description:string|null;image_url:string|null;price:number;old_price:number|null;published:boolean};
const catalogCategory=(name:string)=>/كفر|جراب|case/i.test(name)?'الكفرات':/حماي|لزق|screen|glass/i.test(name)?'الحماية':/شاحن|كيبل|كابل|cable|charger/i.test(name)?'الشواحن':/سماع|headphone|earbud/i.test(name)?'السماعات':'إكسسوارات';
const toItem=(p:PublicListing):Item=>({id:stableProductId(p.id),name:p.name,price:Number(p.price),old:p.old_price?Number(p.old_price):undefined,category:catalogCategory(p.name),image:p.image_url||'',kind:'',compatible:[]});
const normalizeSearch=(value:string)=>value.toLocaleLowerCase('ar').normalize('NFKD').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/[\s\-_]+/g,' ').trim();
const searchableText=(p:Item)=>normalizeSearch([p.name,p.category,p.kind||'',...(p.compatible||[]),p.category==='الشواحن'?'type c تايب سي usb c شحن':'',p.category==='الكفرات'?'جراب غطاء case':'',p.category==='الحماية'?'لزقة لزقات حماية شاشة screen protector':'',p.category==='السماعات'?'earbuds headphones بلوتوث':''].join(' '));
const matchesSearch=(p:Item,q:string)=>normalizeSearch(q).split(' ').filter(Boolean).every(token=>searchableText(p).includes(token));
const sections = [{name:'الكفرات',icon:Smartphone,image:photos.case},{name:'الحماية',icon:ShieldCheck,image:photos.phone},{name:'الشواحن',icon:Zap,image:photos.charger},{name:'السماعات',icon:Headphones,image:photos.earbuds}];
const categoryConfig:Record<string,{slug:string;headline:string;description:string;image:string;chips:string[]}>= {
 'الكفرات':{slug:'cases',headline:'كفرات تعكس شخصيتك.',description:'حماية وأناقة في كل تفصيلة.',image:photos.case,chips:['الكل','Apple','Samsung','Xiaomi']},
 'الحماية':{slug:'protection',headline:'حماية تستحق الثقة.',description:'خيارات لحماية شاشة هاتفك.',image:photos.phone,chips:['الكل','Apple','Samsung','Xiaomi']},
 'الشواحن':{slug:'charging',headline:'طاقة تواكب يومك.',description:'شواحن وكوابل لاحتياجاتك اليومية.',image:photos.charger,chips:['الكل','USB-C','لاسلكي']},
 'السماعات':{slug:'audio',headline:'استمتع بكل تفصيلة.',description:'سماعات تناسب أسلوب حياتك.',image:photos.earbuds,chips:['الكل','لاسلكية','سلكية']}
};
type InfoPage = 'about'|'contact'|'delivery'|'returns'|'tracking';
